{"command":"python - << 'PY'
import os, textwrap, stat, chess, chess.engine, tempfile, uuid, sys
script_path = '/tmp/dummy_engine_'+str(uuid.uuid4())
code = textwrap.dedent('''
#!/usr/bin/env python3
import sys, time

def send(line):
    sys.stdout.write(line+'\n')
    sys.stdout.flush()

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        cmd = line.strip()
        if cmd == 'uci':
            send('id name DummyEngine')
            send('id author GPT')
            send('uciok')
        elif cmd == 'isready':
            send('readyok')
        elif cmd.startswith('setoption'):
            continue
        elif cmd == 'ucinewgame':
            continue
        elif cmd.startswith('position'):
            continue
        elif cmd.startswith('go'):
            # Immediately provide evaluation
            send('info depth 1 score cp -10000')
            send('bestmove 0000')
        elif cmd == 'quit':
            break

if __name__ == '__main__':
    main()
''')
with open(script_path, 'w') as f:
    f.write(code)
os.chmod(script_path, 0o755)

# now test with python-chess
eng = chess.engine.SimpleEngine.popen_uci(script_path)
board = chess.Board()
info = eng.analyse(board, chess.engine.Limit(depth=1))
print(info['score'].white().score())
eng.quit()
